<script setup lang="ts">
import {ref} from 'vue';import {type Execution,type Table} from '../api';import ResultTable from './ResultTable.vue';
import {useLab} from '../store';const lab=useLab();const emit=defineEmits<{insert:[reference:{relation:string,column?:string}]}>();
const preview=ref<Table>();const previewName=ref('');async function show(name:string){const quoted=lab.engine==='mysql'?'`'+name.replaceAll('`','``')+'`':'"'+name.replaceAll('"','""')+'"';const r=await lab.run<Execution>('preview','execute',{sql:`SELECT * FROM ${quoted} LIMIT 100`});if(r){preview.value=r.results[0]?.table;previewName.value=name;}}
</script>
<template><aside class="schema-explorer"><div class="sidebar-title">DATABASE <button title="刷新结构" @click="lab.refresh">↻</button></div><div class="database-name"><span class="online-dot"/>{{lab.engine==='sqlite'?lab.workspace?.fixture:'MySQL 教学库'}}</div><details v-for="relation in lab.schema.relations" :key="relation.name" :data-relation="relation.name" open><summary @dblclick="emit('insert',{relation:relation.name})"><span class="table-icon">▦</span>{{relation.name}}<button class="preview-button" @click.stop.prevent="show(relation.name)">预览</button><small>{{relation.kind==='view'?'视图':''}}</small></summary><button v-for="column in relation.columns" :key="column.name" class="column-row" :data-column="column.name" :title="`${column.data_type} ${column.nullable?'':'NOT NULL'} ${column.default??''}`" @dblclick="emit('insert',{relation:relation.name,column:column.name})"><span :class="{'key-icon':column.primary_key}">{{column.primary_key?'◆':'·'}}</span>{{column.name}}<small>{{column.data_type}}</small></button><details v-if="relation.foreign_keys.length||relation.indexes.length" class="constraints"><summary>键与索引</summary><p v-for="fk in relation.foreign_keys" :key="fk.columns.join()">{{fk.columns.join(',')}} → {{fk.target}}.{{fk.target_columns.join(',')}}</p><p v-for="index in relation.indexes" :key="index">⌕ {{index}}</p></details></details><details v-if="lab.schema.routines.length"><summary>例程与触发器</summary><p v-for="r in lab.schema.routines" :key="r" class="routine-name">{{r}}</p></details><section v-if="preview" class="schema-preview"><button @click="preview=undefined">关闭预览</button><ResultTable :table="preview" :title="previewName+' · 前 100 行'" compact/></section><div class="sidebar-foot">双击表或列插入编辑器<br>结构变更后自动刷新</div></aside></template>
